import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"沉江","description":"","frontmatter":{"title":"沉江","date":"2026-11-24T00:00:00.000Z","seq":32,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"东方朔","source_book":"楚辞","prev":{"text":"初放","link":"/blogs/楚辞/初放.html"},"next":{"text":"怨世","link":"/blogs/楚辞/怨世.html"}},"headers":[],"relativePath":"blogs/楚辞/沉江.md","filePath":"blogs/楚辞/沉江.md"}'),o={name:"blogs/楚辞/沉江.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="沉江" tabindex="-1">沉江 <a class="header-anchor" href="#沉江" aria-label="Permalink to &quot;沉江&quot;">​</a></h1><p class="poem-meta">先秦 · 东方朔　·　七谏</p><div class="poem"><p class="poem-stanza">惟往古之得失兮，览私微之所伤。</p><p class="poem-stanza">尧舜圣而慈仁兮，後世称而弗忘。</p><p class="poem-stanza">齐桓失于专任兮，夷吾忠而名彰。</p><p class="poem-stanza">晋献惑于孋姬兮，申生孝而被殃。</p><p class="poem-stanza">偃王行其仁义兮，荆文寤而徐亡。</p><p class="poem-stanza">纣暴虐以失位兮，周得佐乎吕望。</p><p class="poem-stanza">修往古以行恩兮，封比干之丘垄。</p><p class="poem-stanza">贤俊慕而自附兮，日浸淫而合同。</p><p class="poem-stanza">明法令而修理兮，兰芷幽而有芳。</p><p class="poem-stanza">苦众人之妒予兮，箕子寤而佯狂。</p><p class="poem-stanza">不顾地以贪名兮，心怫郁而内伤。</p><p class="poem-stanza">联蕙芷以为佩兮，过鲍肆而失香。</p><p class="poem-stanza">正臣端其操行兮，反离谤而见攘。</p><p class="poem-stanza">世俗更而变化兮，伯夷饿于首阳。</p><p class="poem-stanza">独廉洁而不容兮，叔齐久而逾明。</p><p class="poem-stanza">浮云陈而蔽晦兮，使日月乎无光。</p><p class="poem-stanza">忠臣贞而欲谏兮，谗谀毁而在旁。</p><p class="poem-stanza">秋草荣其将实兮，微霜下而夜降。</p><p class="poem-stanza">商风肃而害生兮，百草育而不长。</p><p class="poem-stanza">众并谐以妒贤兮，孤圣特而易伤。</p><p class="poem-stanza">怀计谋而不见用兮，岩穴处而隐藏。</p><p class="poem-stanza">成功隳而不卒兮，子胥死而不葬。</p><p class="poem-stanza">世从俗而变化兮，随风靡而成行。</p><p class="poem-stanza">信直退而毁败兮，虚伪进而得当。</p><p class="poem-stanza">追悔过之无及兮，岂尽忠而有功。</p><p class="poem-stanza">废制度而不用兮，务行私而去公。</p><p class="poem-stanza">终不变而死节兮，惜年齿之未央。</p><p class="poem-stanza">将方舟而下流兮，冀幸君之发矇。</p><p class="poem-stanza">痛忠言之逆耳兮，恨申子之沉江。</p><p class="poem-stanza">愿悉心之所闻兮，遭值君之不聪。</p><p class="poem-stanza">不开寤而难道兮，不别横之与纵。</p><p class="poem-stanza">听奸臣之浮说兮，绝国家之久长。</p><p class="poem-stanza">灭规矩而不用兮，背绳墨之正方。</p><p class="poem-stanza">离忧患而乃寤兮，若纵火于秋蓬。</p><p class="poem-stanza">业失之而不救兮，尚何论乎祸凶。</p><p class="poem-stanza">彼离畔而朋党兮，独行之士其何望？</p><p class="poem-stanza">日渐染而不自知兮，秋毫微哉而变容。</p><p class="poem-stanza">众轻积而折轴兮，原咎杂而累重。</p><p class="poem-stanza">赴湘沅之流澌兮，恐逐波而复东。</p><p class="poem-stanza">怀沙砾而自沉兮，不忍见君之蔽壅。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
